import{d as t,S as a,i as o,l as s}from"./chunks/framework.CY2TYXqZ.js";const g=JSON.parse('{"title":"Workshop: start, save, and leave","description":"","frontmatter":{},"headers":[],"relativePath":"guide/workshop.md","filePath":"guide/workshop.md"}'),r={name:"guide/workshop.md"};function n(i,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="workshop-start-save-and-leave" tabindex="-1">Workshop: start, save, and leave <a class="header-anchor" href="#workshop-start-save-and-leave" aria-label="Permalink to “Workshop: start, save, and leave”">​</a></h1><p>WXL runs challenges in the browser. Attack logs, notes, Code drafts, and challenge progress stay in this device&#39;s browser storage for this site. There is no account sync or automatic submission to a teacher.</p><h2 id="shared-classroom-computers" tabindex="-1">Shared classroom computers <a class="header-anchor" href="#shared-classroom-computers" aria-label="Permalink to “Shared classroom computers”">​</a></h2><ol><li>Check whose work is stored before starting. Choose <strong>Continue with this work</strong> only when it is yours. For a previous participant&#39;s work, choose <strong>Delete it and start fresh</strong>. Deletion cannot be undone.</li><li>While the choice is pending, previous completion counts and badges are hidden and flag submission is disabled. If clearing is unconfirmed, close the other site tabs and reload as instructed before continuing.</li><li>Before leaving, export the attack log from every challenge you need to keep; unsolved work can also be exported. Choose <strong>Full</strong> to retain the most content. Open the downloaded file to check it, then move it to your own storage.</li><li>One export contains the single attempt you chose, not a backup of the whole browser. Copy any unsaved note text separately.</li><li>Close all site tabs before handing over the computer. The next participant should reopen the site and clear the previous work. An open tab cannot identify that a different person has taken the seat. Remove personal downloads from the shared computer according to classroom rules.</li></ol><h2 id="personal-devices" tabindex="-1">Personal devices <a class="header-anchor" href="#personal-devices" aria-label="Permalink to “Personal devices”">​</a></h2><ul><li>Return using the same device, browser, and site address, keeping its stored data. If asked, confirm that the work is yours before continuing.</li><li>The latest unsolved session resumes when eligible. Returning to a solved challenge starts a new session while retaining the previous one. The challenge page lists every attempt stored for that challenge, and any of them can be chosen for export — not only the attempt in progress.</li><li>Changing browsers or devices does not carry the data over on its own. Take the downloaded JSON to the other device and import it from the same challenge&#39;s page.</li><li>An import always adds one record. It never replaces or merges an existing one, and it changes neither challenge progress nor the editor draft. An imported record can be read and exported again, but new work is not appended to it — to carry on with the challenge, start a fresh attempt.</li><li>Import a file from the page of the challenge it belongs to. A file for a different challenge is refused, naming both challenges; it is never stored under the challenge you have open.</li><li>The integrity check shown on import says only that the file&#39;s content matches the hashes inside it. It does not say who produced the file.</li></ul><h2 id="read-the-result-and-the-saving-status-separately" tabindex="-1">Read the result and the saving status separately <a class="header-anchor" href="#read-the-result-and-the-saving-status-separately" aria-label="Permalink to “Read the result and the saving status separately”">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Meaning</th><th>Action</th></tr></thead><tbody><tr><td>Verification and saving in progress</td><td>Submission has not finished</td><td>Wait rather than resubmitting</td></tr><tr><td>Correct flag and saved</td><td>The answer is correct and this submission was saved</td><td>Export the work you need</td></tr><tr><td>Correct flag and incompletely saved</td><td>The answer is correct, but saving did not fully succeed</td><td>Keep any available export; another submission counts as another attempt</td></tr><tr><td>Unable to verify</td><td>No valid answer determination was obtained</td><td>Wait for the runtime and retry</td></tr><tr><td>Unable to read progress</td><td>Existing progress could not be confirmed; this does not mean zero completion or deletion</td><td>Retry the read, then follow storage guidance if needed</td></tr></tbody></table><h2 id="platform-updates" tabindex="-1">Platform updates <a class="header-anchor" href="#platform-updates" aria-label="Permalink to “Platform updates”">​</a></h2><p>Before the workshop, export important work, close the other site tabs, and reload. An old page may be unable to use an upgraded database; reloading loads the new application code. Database preservation does not preserve the challenge&#39;s running environment: logins, uploaded files, and unsaved actions may need to be repeated after reloading.</p><p>If a storage warning appears, save available exports and unsaved text first. Do not clear site data as a routine troubleshooting step.</p><h2 id="suggested-demonstration" tabindex="-1">Suggested demonstration <a class="header-anchor" href="#suggested-demonstration" aria-label="Permalink to “Suggested demonstration”">​</a></h2><p>Show keep versus clear, open a challenge, submit an answer while explaining the separate saving status, then download and open a full attack log. Arrange a separate file submission channel if you want to collect work; WXL does not collect it automatically.</p><p>See <a href="./notes#export">notes and export</a> and <a href="./troubleshooting">troubleshooting</a> for details.</p>',14)])])}const u=t(r,[["render",n]]);export{g as __pageData,u as default};
